{
  "name": "Modbus TCP从站设备",
  "name_en": "Modbus TCP slave device",
  "manufacturer": "",
  "description": "支持 Modbus TCP 协议的工业现场设备，如 PLC、远程 I/O 模块、仪表或控制器。实验室中常通过以太网读取线圈、离散输入和寄存器数据，并写入控制位或设定值，用于设备监测、数据采集、联机调试和自动化控制实验。",
  "description_en": "An industrial field device that supports the Modbus TCP protocol, such as a PLC, remote I/O module, meter, or controller. In laboratory use, it is commonly accessed over Ethernet to read coils, discrete inputs, and registers, and to write control bits or setpoints for equipment monitoring, data acquisition, integration testing, and automation experiments.",
  "tag_hints": [
    "Modbus TCP",
    "industrial Ethernet",
    "PLC communication",
    "remote I/O",
    "register read/write",
    "process automation"
  ],
  "actions": [
    {
      "action_name": "read_coils",
      "description": "读取线圈状态",
      "description_en": "Read coil status"
    },
    {
      "action_name": "read_discrete_inputs",
      "description": "读取离散输入状态",
      "description_en": "Read discrete input status"
    },
    {
      "action_name": "write_coil",
      "description": "写入单个线圈状态",
      "description_en": "Write a single coil state"
    },
    {
      "action_name": "write_coils",
      "description": "写入多个线圈状态",
      "description_en": "Write multiple coil states"
    },
    {
      "action_name": "write_register",
      "description": "写入单个保持寄存器",
      "description_en": "Write a single holding register"
    },
    {
      "action_name": "write_registers",
      "description": "写入多个保持寄存器",
      "description_en": "Write multiple holding registers"
    },
    {
      "action_name": "read_holding_registers",
      "description": "读取保持寄存器",
      "description_en": "Read holding registers"
    },
    {
      "action_name": "read_input_registers",
      "description": "读取输入寄存器",
      "description_en": "Read input registers"
    },
    {
      "action_name": "readwrite_registers",
      "description": "同时读取并写入寄存器",
      "description_en": "Read and write registers in one operation"
    },
    {
      "action_name": "mask_write_register",
      "description": "按位掩码写入单个寄存器",
      "description_en": "Mask-write a single register"
    },
    {
      "action_name": "read_device_information",
      "description": "读取设备识别信息",
      "description_en": "Read device identification information"
    },
    {
      "action_name": "report_slave_id",
      "description": "读取从站标识",
      "description_en": "Read the slave ID"
    },
    {
      "action_name": "read_exception_status",
      "description": "读取异常状态",
      "description_en": "Read exception status"
    },
    {
      "action_name": "get_com_event_counter",
      "description": "获取通信事件计数器",
      "description_en": "Get the communication event counter"
    },
    {
      "action_name": "get_com_event_log",
      "description": "获取通信事件日志",
      "description_en": "Get the communication event log"
    },
    {
      "action_name": "return_query_data",
      "description": "返回查询数据",
      "description_en": "Return query data"
    },
    {
      "action_name": "restart_comm_option",
      "description": "重启通信并设置通信选项",
      "description_en": "Restart communications and set communication options"
    },
    {
      "action_name": "return_diagnostic_register",
      "description": "返回诊断寄存器内容",
      "description_en": "Return diagnostic register contents"
    },
    {
      "action_name": "change_ascii_input_delimiter",
      "description": "更改 ASCII 输入分隔符",
      "description_en": "Change the ASCII input delimiter"
    },
    {
      "action_name": "force_listen_only_mode",
      "description": "强制进入仅监听模式",
      "description_en": "Force listen-only mode"
    },
    {
      "action_name": "clear_counters",
      "description": "清除通信计数器",
      "description_en": "Clear communication counters"
    },
    {
      "action_name": "return_bus_message_count",
      "description": "返回总线消息计数",
      "description_en": "Return the bus message count"
    },
    {
      "action_name": "return_bus_com_error_count",
      "description": "返回总线通信错误计数",
      "description_en": "Return the bus communication error count"
    },
    {
      "action_name": "return_bus_exception_error_count",
      "description": "返回总线异常错误计数",
      "description_en": "Return the bus exception error count"
    },
    {
      "action_name": "return_slave_message_count",
      "description": "返回从站消息计数",
      "description_en": "Return the slave message count"
    },
    {
      "action_name": "return_slave_no_response_count",
      "description": "返回从站无响应计数",
      "description_en": "Return the slave no-response count"
    },
    {
      "action_name": "return_slave_no_ack_count",
      "description": "返回从站未确认计数",
      "description_en": "Return the slave no-acknowledge count"
    },
    {
      "action_name": "return_slave_busy_count",
      "description": "返回从站忙计数",
      "description_en": "Return the slave busy count"
    },
    {
      "action_name": "return_slave_bus_char_overrun_count",
      "description": "返回从站总线字符溢出计数",
      "description_en": "Return the slave bus character overrun count"
    },
    {
      "action_name": "return_iop_overrun_count",
      "description": "返回 IOP 溢出计数",
      "description_en": "Return the IOP overrun count"
    },
    {
      "action_name": "clear_overrun_count",
      "description": "清除溢出计数",
      "description_en": "Clear the overrun count"
    },
    {
      "action_name": "get_clear_modbus_plus",
      "description": "获取或清除 Modbus Plus 统计信息",
      "description_en": "Get or clear Modbus Plus statistics"
    }
  ]
}

